{
  # A host-only /30: physical LAN configuration stays in the host baseline.
  networking.dhcpcd.denyInterfaces = [ "vm-*" ];
  systemd.network.enable = true;
  systemd.network.networks."20-test-vm" = {
    matchConfig.Name = "vm-test";
    address = [ "10.80.0.1/30" ];
    networkConfig = {
      DHCP = "no";
      LinkLocalAddressing = "no";
      IPv6AcceptRA = false;
    };
    linkConfig.RequiredForOnline = "no";
  };
  microvm.vms.test-vm = {
    autostart = true;
    config = {
      imports = [
        nexus-infra.nixosModules.vm-base
        ../vms/test-vm
      ];
      microvm.interfaces = [{
        type = "tap";
        id = "vm-test";
        mac = "02:00:00:00:80:02";
      }];
      systemd.network.networks."20-host" = {
        matchConfig.MACAddress = "02:00:00:00:80:02";
        address = [ "10.80.0.2/30" ];
        networkConfig = {
          DHCP = "no";
          LinkLocalAddressing = "no";
          IPv6AcceptRA = false;
        };
      };
      # Resolve the guest's named storage request to this host's backing path.
      microvm.shares = [{
        tag = "test-data";
        proto = "virtiofs";
        source = "/srv/nexus-storage/test-vm/test-data";
        mountPoint = "/data";
      }];
    };
  };
  # Never start a guest or its share daemon against an unmounted backing disk.
  systemd.services."microvm@test-vm".unitConfig.RequiresMountsFor = [ "/srv/nexus-storage" ];
  systemd.services."microvm-virtiofsd@test-vm".unitConfig.RequiresMountsFor = [ "/srv/nexus-storage" ];
  systemd.services.test-vm-storage = {
    description = "Create declared VM shares after mounting persistent storage";
    requiredBy = [ "microvm-virtiofsd@test-vm.service" ];
    before = [ "microvm-virtiofsd@test-vm.service" ];
    unitConfig.RequiresMountsFor = [ "/srv/nexus-storage" ];
    serviceConfig = {
      Type = "oneshot";
      RemainAfterExit = true;
      ExecStart = "${pkgs.systemd}/bin/systemd-tmpfiles --create --prefix=/srv/nexus-storage";
    };
  };
}
FILE /etc/nixos/Nexus-Infra-Private/vms/test-vm/default.nix
{ pkgs, ... }:
{
  networking.hostName = "test-vm";
  networking.firewall.allowedTCPPorts = [ 8080 ];
  # This guest asks for a named share, without knowing the physical backing disk.
  fileSystems."/data" = {
    device = "test-data";
    fsType = "virtiofs";
  };
  environment.etc."test-vm-revision".text = "2\n";
  systemd.services.test-data-init = {
    description = "Write a persistence marker from inside test-vm";
    wantedBy = [ "multi-user.target" ];
    before = [ "test-http.service" ];
    unitConfig.RequiresMountsFor = [ "/data" ];
    serviceConfig = {
      Type = "oneshot";
      RemainAfterExit = true;
    };
    script = ''
      set -eu
      if [ ! -e /data/persistence-proof.txt ]; then
        printf 'Nexus test-vm persistent data; first boot: %s\n' "$(cat /proc/sys/kernel/random/boot_id)" > /data/persistence-proof.txt
      fi
      mkdir -p /run/test-vm
      ln -s /data/persistence-proof.txt /run/test-vm/persistence-proof.txt
      cat /proc/sys/kernel/random/boot_id > /run/test-vm/boot-id.txt
      cp /etc/test-vm-revision /run/test-vm/revision.txt
      printf 'test-vm is running\n' > /run/test-vm/index.html
    '';
  };
  systemd.services.test-http = {
    description = "Host-only test HTTP service";
    wantedBy = [ "multi-user.target" ];
    requires = [ "test-data-init.service" ];
    after = [ "test-data-init.service" "network-online.target" ];
    wants = [ "network-online.target" ];
    serviceConfig = {
      DynamicUser = true;
      ExecStart = "${pkgs.python3}/bin/python -m http.server 8080 --bind 10.80.0.2 --directory /run/test-vm";
      Restart = "on-failure";
      NoNewPrivileges = true;
      ProtectSystem = "strict";
      ProtectHome = true;
      PrivateTmp = true;
    };
  };
}
