let
  # Concrete placement, addresses and logical-to-local storage mappings.
  guests = {
    test-vm = {
      ip = "10.80.0.2"; mac = "02:00:00:00:80:02"; tap = "vm-test";
      module = ../vms/test-vm;
      storage = { test-data = "test-vm/test-data"; vm-state = "test-vm/vm-state"; };
    };
    network-control = {
      ip = "10.80.0.3"; mac = "02:00:00:00:80:03"; tap = "vm-control";
      module = ../vms/network-control;
      storage = { control-state = "network-control/control-state"; vm-state = "network-control/vm-state"; };
    };
    ingress = {
      ip = "10.80.0.4"; mac = "02:00:00:00:80:04"; tap = "vm-ingress";
      module = ../vms/ingress;
      storage = { ingress-state = "ingress/ingress-state"; vm-state = "ingress/vm-state"; };
    };
  };
in
{
  networking.dhcpcd.denyInterfaces = [ "vm-*" "br-nexus" ];
  systemd.network = {
    enable = true;
    netdevs."20-nexus".netdevConfig = { Name = "br-nexus"; Kind = "bridge"; };
    networks."20-nexus" = {
      matchConfig.Name = "br-nexus";
      address = [ "10.80.0.1/24" ];
      networkConfig = {
        ConfigureWithoutCarrier = true;
        DHCP = "no";
        LinkLocalAddressing = "no";
        IPv6AcceptRA = false;
      };
      linkConfig.RequiredForOnline = "no";
    };
    networks."21-nexus-taps" = {
      matchConfig.Name = "vm-*";
      networkConfig = {
        Bridge = "br-nexus";
        DHCP = "no";
        LinkLocalAddressing = "no";
        IPv6AcceptRA = false;
      };
      linkConfig.RequiredForOnline = "no";
    };
  };
  microvm.vms = lib.mkMerge [ (lib.mapAttrs (_: guest: {
    autostart = true;
    config = {
      imports = [
        nexus-infra.nixosModules.vm-base
        nexus-infra.nixosModules.vm-persistent
        ../vms/common.nix
        guest.module
      ];
      nexus.persistence = lib.mapAttrs (_: relativePath: {
        source = "${nexusStorageRoot}/${relativePath}";
      }) guest.storage;
      microvm.interfaces = [{ type = "tap"; id = guest.tap; mac = guest.mac; }];
      systemd.network.networks."20-private" = {
        matchConfig.MACAddress = guest.mac;
        address = [ "${guest.ip}/24" ];
        networkConfig = { DHCP = "no"; LinkLocalAddressing = "no"; IPv6AcceptRA = false; };
      };
    };
  }) guests) {
    network-control.config = {
      systemd.network.networks."20-private".networkConfig.Gateway = "10.80.0.1";
      networking.nameservers = [ "192.168.178.1" ];
      services.headscale.settings.server_url = "http://${guests.network-control.ip}:8080";
    };
    ingress.config.services.traefik.dynamicConfigOptions.http.services.test-vm.loadBalancer.servers = [
      { url = "http://${guests.test-vm.ip}:8080"; }
    ];
  } ];
  # Only the control plane needs egress for the standard upstream DERP map.
  # This is not a relay or a default route for other Nexus workloads.
  networking.nat = {
    enable = true;
    externalInterface = "enp27s0";
    internalIPs = [ "${guests.network-control.ip}/32" ];
  };
  # LAN-only TCP entry point; HTTP routing happens inside the ingress VM.
  networking.firewall.interfaces.enp27s0.allowedTCPPorts = [ 8080 ];
  systemd.sockets.nexus-ingress = {
    wantedBy = [ "sockets.target" ];
    listenStreams = [ "192.168.178.192:8080" ];
    socketConfig.FreeBind = true;
  };
  systemd.services.nexus-ingress = {
    requires = [ "microvm@ingress.service" ];
    after = [ "microvm@ingress.service" ];
    serviceConfig = {
      ExecStart = "${pkgs.systemd}/lib/systemd/systemd-socket-proxyd ${guests.ingress.ip}:80";
      DynamicUser = true;
      NoNewPrivileges = true;
      ProtectSystem = "strict";
      ProtectHome = true;
    };
  };
