                item.update(capacityBytes=stat.f_blocks*stat.f_frsize, usedBytes=(stat.f_blocks-stat.f_bfree)*stat.f_frsize, availableBytes=stat.f_bavail*stat.f_frsize, mounted=os.path.ismount(backend['mountPoint']))
