            'metrics': {'cpuPercent': cpu, 'memoryTotalBytes': mem['MemTotal'], 'memoryUsedBytes': mem['MemTotal']-mem['MemAvailable'], 'uptimeSeconds': float(Path('/proc/uptime').read_text().split()[0]), 'load': list(os.getloadavg())},
