# Nexus Infra
Reusable NixOS host and MicroVM modules. Dependencies point from a deployment to this public repository, never back to a private deployment.
- `nixosModules.host-base`: physical-host baseline.
- `nixosModules.microvm-host`: pinned upstream MicroVM host integration. For fully declarative guests, backing filesystems are required before share directories, virtiofs daemons and guests start.
- `nixosModules.vm-base`: small QEMU/KVM guest defaults and a read-only host Nix-store share.
- `nixosModules.vm-persistent`: named persistent directory requests using virtiofs.
A guest requests `nexus.persistence.<name>.mountPoint`. Its deployment supplies `nexus.persistence.<name>.source`. The module produces the virtiofs share; the host module orders startup against the actual backing filesystem. Disk identities, concrete paths, VM names, addresses and placements remain in the deployment.
Import guest modules through `microvm.vms.<name>.config`. Set this flake's `nixpkgs` input to follow the deployment's package set. The lock file pins upstream dependencies.
Upstream: https://microvm-nix.github.io/microvm.nix/declarative.html
{
  description = "Nexus Infra - reusable NixOS infrastructure modules";
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-26.05";
    microvm.url = "github:microvm-nix/microvm.nix";
    microvm.inputs.nixpkgs.follows = "nixpkgs";
  };
  outputs = { microvm, ... }: {
    nixosModules = {
      host-base = import ./host-modules/base.nix;
      microvm-host = {
        imports = [
          microvm.nixosModules.host
          ./host-modules/microvm-host.nix
        ];
      };
      vm-base = import ./vm-modules/base.nix;
      vm-persistent = import ./vm-modules/persistent.nix;
      nexus-agent = import ./host-modules/nexus-agent.nix;
      nexus-console = import ./vm-modules/console.nix;
    };
  };
}
{ pkgs, ... }:
{
  nix.settings.experimental-features = [
    "nix-command"
    "flakes"
  ];
  boot.loader.systemd-boot.enable = true;
  boot.loader.efi.canTouchEfiVariables = true;
  networking.useDHCP = true;
  services.openssh = {
    enable = true;
    settings = {
      PermitRootLogin = "no";
      PasswordAuthentication = true;
    };
  };
  environment.systemPackages = with pkgs; [
    git
    vim
    curl
    htop
  ];
  time.timeZone = "Europe/Berlin";
  system.stateVersion = "26.05";
}
{ lib, ... }:
{
  microvm = {
    hypervisor = lib.mkDefault "qemu";
    vcpu = lib.mkDefault 1;
    mem = lib.mkDefault 256;
    shares = [{
      proto = "virtiofs";
      tag = "ro-store";
      source = "/nix/store";
      mountPoint = "/nix/.ro-store";
      readOnly = true;
    }];
  };
  networking.useDHCP = false;
  networking.useNetworkd = true;
  system.stateVersion = lib.mkDefault "26.05";
}
{ config, lib, ... }:
{
  options.nexus.persistence = lib.mkOption {
    default = { };
    description = "Named guest storage requests, with backing directories assigned by the deployment.";
    type = lib.types.attrsOf (lib.types.submodule {
      options = {
        mountPoint = lib.mkOption {
          type = lib.types.str;
          description = "Absolute mount point inside the guest.";
        };
        source = lib.mkOption {
          type = lib.types.str;
          description = "Absolute host directory supplied by the deployment's storage mapping.";
        };
      };
    });
  };
  config = {
    assertions = lib.mapAttrsToList (name: storage: {
      assertion = builtins.match "[a-zA-Z0-9_-]+" name != null
        && lib.hasPrefix "/" storage.mountPoint
        && lib.hasPrefix "/" storage.source;
      message = "Persistent share ${name} requires a simple name and absolute host/guest paths.";
    }) config.nexus.persistence;
    microvm.shares = lib.mapAttrsToList (name: storage: {
      tag = name;
      proto = "virtiofs";
      inherit (storage) source mountPoint;
    }) config.nexus.persistence;
  };
}

